import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

hinge_loss_cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void hinge_loss_sum_elementwise_kernel(
    const float* __restrict__ preds,
    const float* __restrict__ targets,
    float* __restrict__ out_sum,
    size_t numel
) {
    extern __shared__ float sdata[];
    size_t tid = threadIdx.x;
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = blockDim.x * gridDim.x;

    float local = 0.0f;
    for (size_t i = idx; i < numel; i += stride) {
        float h = 1.0f - preds[i] * targets[i];
        if (h > 0.0f) local += h;
    }

    sdata[tid] = local;
    __syncthreads();

    // Block reduction
    for (unsigned int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(out_sum, sdata[0]);
    }
}

__global__ void hinge_loss_sum_row_broadcast_kernel(
    const float* __restrict__ preds,
    const float* __restrict__ targets_row, // length = outer (size of dim 0)
    float* __restrict__ out_sum,
    size_t numel,
    size_t inner,  // product of dims 1..end
    size_t outer   // preds.size(0)
) {
    extern __shared__ float sdata[];
    size_t tid = threadIdx.x;
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = blockDim.x * gridDim.x;

    float local = 0.0f;
    for (size_t i = idx; i < numel; i += stride) {
        size_t row = i / inner;
        float t = targets_row[row];
        float h = 1.0f - preds[i] * t;
        if (h > 0.0f) local += h;
    }

    sdata[tid] = local;
    __syncthreads();

    // Block reduction
    for (unsigned int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(out_sum, sdata[0]);
    }
}

torch::Tensor hinge_loss_mean_cuda(torch::Tensor predictions, torch::Tensor targets) {
    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.dtype() == torch::kFloat32, "predictions must be float32");
    TORCH_CHECK(targets.dtype() == torch::kFloat32, "targets must be float32");

    auto preds = predictions.contiguous();
    auto targs = targets.contiguous();

    const auto numel = static_cast<size_t>(preds.numel());
    TORCH_CHECK(numel > 0, "Empty predictions tensor");

    auto options = preds.options();
    auto sum_tensor = torch::zeros({1}, options);
    float* out_sum = sum_tensor.data_ptr<float>();

    const int threads = 256;
    int maxBlocks = 65535;
    int blocks = (int)((numel + threads - 1) / threads);
    if (blocks > maxBlocks) blocks = maxBlocks;

    size_t shared = threads * sizeof(float);

    bool done = false;

    // Case 1: Exact elementwise match
    if (targs.numel() == preds.numel() && targs.sizes() == preds.sizes()) {
        hinge_loss_sum_elementwise_kernel<<<blocks, threads, shared>>>(
            preds.data_ptr<float>(),
            targs.data_ptr<float>(),
            out_sum,
            numel
        );
        done = true;
    } else {
        // Case 2: Row broadcast (targets is 1D and matches first dimension of predictions)
        if (targs.dim() == 1 && preds.dim() >= 1 && targs.size(0) == preds.size(0)) {
            size_t outer = static_cast<size_t>(preds.size(0));
            size_t inner = numel / outer;
            hinge_loss_sum_row_broadcast_kernel<<<blocks, threads, shared>>>(
                preds.data_ptr<float>(),
                targs.data_ptr<float>(),
                out_sum,
                numel,
                inner,
                outer
            );
            done = true;
        }
    }

    // Fallback: use ATen ops (still on CUDA) if pattern not handled above
    if (!done) {
        auto tmp = 1.0f - preds * targs;
        auto clamped = at::clamp_min(tmp, 0.0);
        return clamped.mean();
    }

    // Convert sum to mean
    auto mean = sum_tensor / static_cast<float>(numel);
    return mean.squeeze();
}
"""

hinge_loss_cpp_decl = "torch::Tensor hinge_loss_mean_cuda(torch::Tensor predictions, torch::Tensor targets);"

hinge_loss_ext = load_inline(
    name="hinge_loss_fused",
    cpp_sources=[hinge_loss_cpp_decl],
    cuda_sources=[hinge_loss_cuda_source],
    functions=["hinge_loss_mean_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model computing Hinge Loss with a fused CUDA kernel:
    mean(max(0, 1 - predictions * targets))
    """
    def __init__(self):
        super().__init__()
        self._op = hinge_loss_ext

    def forward(self, predictions, targets):
        # Ensure dtype and device suitable for our kernel
        if not torch.cuda.is_available():
            # CPU fallback
            return torch.clamp(1 - predictions * targets, min=0).mean()

        preds = predictions.to(device="cuda", dtype=torch.float32, non_blocking=True)
        targs = targets.to(device="cuda", dtype=torch.float32, non_blocking=True)
        return self._op.hinge_loss_mean_cuda(preds, targs)

